"""
Script to reproduce the parameter processing for geometry issue.
"""

import pybamm
import numpy as np

def test_without_parameter_processing():
    """Test case that reproduces the bug - no parameter processing."""
    print("Testing WITHOUT parameter processing...")

    # Create a simple model with no parameters
    model = pybamm.BaseModel()

    # Define a variable
    c = pybamm.Variable("concentration", domain="domain")

    # Simple equation (no parameters)
    model.rhs = {c: -c}
    model.initial_conditions = {c: pybamm.Scalar(1.0)}
    model.variables = {"concentration": c}

    # Define geometry (similar to the create-model.py example)
    x = pybamm.SpatialVariable("x", domain="domain", coord_sys="cartesian")
    geometry = {
        "domain": {"primary": {x: {"min": pybamm.Scalar(0), "max": pybamm.Scalar(1)}}}
    }

    # NOTE: We're NOT calling param.process_geometry(geometry) here
    # This should cause the error

    # Try to create mesh - this should fail
    try:
        submesh_types = {"domain": pybamm.Uniform1DSubMesh}
        var_pts = {x: 10}
        mesh = pybamm.Mesh(geometry, submesh_types, var_pts)
        print("SUCCESS: Mesh created without parameter processing")
        return True
    except Exception as e:
        print(f"ERROR: {type(e).__name__}: {e}")
        return False

def test_with_parameter_processing():
    """Test case that works correctly - with parameter processing."""
    print("\nTesting WITH parameter processing...")

    # Create a simple model with no parameters  
    model = pybamm.BaseModel()

    # Define a variable
    c = pybamm.Variable("concentration", domain="domain")

    # Simple equation (no parameters)
    model.rhs = {c: -c}
    model.initial_conditions = {c: pybamm.Scalar(1.0)}
    model.variables = {"concentration": c}

    # Define geometry
    x = pybamm.SpatialVariable("x", domain="domain", coord_sys="cartesian")
    geometry = {
        "domain": {"primary": {x: {"min": pybamm.Scalar(0), "max": pybamm.Scalar(1)}}}
    }

    # Process with empty parameter values (this should work)
    param = pybamm.ParameterValues({})
    param.process_geometry(geometry)

    # Try to create mesh - this should work
    try:
        submesh_types = {"domain": pybamm.Uniform1DSubMesh}
        var_pts = {x: 10}
        mesh = pybamm.Mesh(geometry, submesh_types, var_pts)
        print("SUCCESS: Mesh created with parameter processing")
        return True
    except Exception as e:
        print(f"ERROR: {type(e).__name__}: {e}")
        return False

if __name__ == "__main__":
    print("Reproducing the parameter processing for geometry issue...\n")

    # Test the failing case
    success1 = test_without_parameter_processing()

    # Test the working case
    success2 = test_with_parameter_processing()

    print(f"\nResults:")
    print(f"Without parameter processing: {'PASS' if success1 else 'FAIL'}")
    print(f"With parameter processing: {'PASS' if success2 else 'FAIL'}")

    if not success1:
        print("\nThe issue is reproduced! Without parameter processing, mesh creation fails.")
    else:
        print("\nUnexpected: Issue not reproduced.")"}

