"""
Analyze the problem more deeply to understand what exactly goes wrong.
"""

import pybamm
import numpy as np

def test_mesh_usage():
    """Test how the mesh is actually used downstream."""
    print("=== Testing mesh usage patterns ===")

    # Create unprocessed geometry
    x = pybamm.SpatialVariable("x", domain="domain", coord_sys="cartesian")
    geometry_unprocessed = {
        "domain": {"primary": {x: {"min": pybamm.Scalar(0), "max": pybamm.Scalar(1)}}}
    }

    # Create mesh with unprocessed geometry
    submesh_types = {"domain": pybamm.Uniform1DSubMesh}
    var_pts = {x: 10}

    print("Creating mesh with unprocessed geometry...")
    mesh = pybamm.Mesh(geometry_unprocessed, submesh_types, var_pts)

    print(f"Mesh created. Domain edges: {mesh['domain'][0].edges}")
    print(f"Edge types: {[type(edge) for edge in mesh['domain'][0].edges]}")

    # Test what happens when we try to use these edges
    print("\nTesting edge usage...")
    edges = mesh['domain'][0].edges

    try:
        # Try to convert to array or use in calculations
        edges_array = np.array(edges)
        print(f"Edges as array: {edges_array}")
        print(f"Array dtype: {edges_array.dtype}")

        # Try to do some math
        result = edges_array + 1
        print(f"Edges + 1: {result}")

    except Exception as e:
        print(f"ERROR in edge usage: {type(e).__name__}: {e}")
        import traceback
        traceback.print_exc()

    # Compare with processed geometry
    print("\n=== Comparing with processed geometry ===")
    geometry_processed = {
        "domain": {"primary": {x: {"min": pybamm.Scalar(0), "max": pybamm.Scalar(1)}}}
    }
    param = pybamm.ParameterValues({})
    param.process_geometry(geometry_processed)

    mesh_processed = pybamm.Mesh(geometry_processed, submesh_types, var_pts)
    edges_processed = mesh_processed['domain'][0].edges

    print(f"Processed edges: {edges_processed}")
    print(f"Processed edge types: {[type(edge) for edge in edges_processed]}")

    try:
        edges_array_proc = np.array(edges_processed)
        print(f"Processed edges as array: {edges_array_proc}")
        print(f"Processed array dtype: {edges_array_proc.dtype}")
    except Exception as e:
        print(f"ERROR with processed edges: {type(e).__name__}: {e}")

def check_if_geometry_needs_processing(geometry):
    """Check if geometry contains unprocessed pybamm.Scalar objects."""
    print("\n=== Checking if geometry needs processing ===")

    needs_processing = False
    for domain in geometry:
        for prim_sec_tabs, variables in geometry[domain].items():
            if prim_sec_tabs != "tabs":
                for spatial_variable, spatial_limits in variables.items():
                    for lim, sym in spatial_limits.items():
                        if isinstance(sym, pybamm.Scalar):
                            print(f"Found unprocessed Scalar in {domain}[{prim_sec_tabs}][{spatial_variable}][{lim}]: {sym}")
                            needs_processing = True
                        else:
                            print(f"Processed value in {domain}[{prim_sec_tabs}][{spatial_variable}][{lim}]: {sym} ({type(sym)})")

    return needs_processing

if __name__ == "__main__":
    test_mesh_usage()

    # Test the checking function
    x = pybamm.SpatialVariable("x", domain="domain", coord_sys="cartesian")

    # Unprocessed
    geo_unprocessed = {
        "domain": {"primary": {x: {"min": pybamm.Scalar(0), "max": pybamm.Scalar(1)}}}
    }
    print(f"Unprocessed geometry needs processing: {check_if_geometry_needs_processing(geo_unprocessed)}")

    # Processed
    geo_processed = {
        "domain": {"primary": {x: {"min": pybamm.Scalar(0), "max": pybamm.Scalar(1)}}}
    }
    param = pybamm.ParameterValues({})
    param.process_geometry(geo_processed)
    print(f"Processed geometry needs processing: {check_if_geometry_needs_processing(geo_processed)}")"}

