import yaml

# Create a loader that combines SafeLoader's composer with BaseLoader's constructor behavior
class RecursionSafeBaseLoader(yaml.SafeLoader):
    """SafeLoader that treats all unknown tags as strings."""

    def construct_undefined(self, node):
        # This mimics BaseLoader's behavior of treating unknown tags as plain data
        if isinstance(node, yaml.ScalarNode):
            return self.construct_scalar(node)
        elif isinstance(node, yaml.SequenceNode):
            return self.construct_sequence(node)
        elif isinstance(node, yaml.MappingNode):
            return self.construct_mapping(node)
        else:
            return super().construct_undefined(node)

