"""Test custom loader with actual ASDF content."""

import asdf
import yaml
import tempfile
import os

# Create our custom loader
class RecursionSafeBaseLoader(yaml.loader.Loader):
    """Loader with SafeLoader's recursion but BaseLoader's tag behavior."""
    pass

def construct_passthrough(loader, node):
    """Construct node data without interpreting tags."""
    if isinstance(node, yaml.ScalarNode):
        return loader.construct_scalar(node)
    elif isinstance(node, yaml.SequenceNode):
        return loader.construct_sequence(node)
    elif isinstance(node, yaml.MappingNode):
        return loader.construct_mapping(node)
    else:
        return None

RecursionSafeBaseLoader.add_constructor(None, construct_passthrough)

def test_with_real_asdf():
    """Test with real ASDF file content."""
    print("Creating recursive object...")
    d = {}
    d['a'] = d

    # Create a temporary file
    with tempfile.NamedTemporaryFile(suffix='.asdf', delete=False) as tmp:
        temp_filename = tmp.name

    try:
        print(f"Writing to {temp_filename}")
        asdf.AsdfFile(d).write_to(temp_filename)

        # Extract just the YAML part
        with open(temp_filename, 'rb') as f:
            content = f.read()
            # Find the YAML end marker
            yaml_end_marker = b'\n...\n'
            yaml_end_pos = content.find(yaml_end_marker)
            if yaml_end_pos != -1:
                yaml_content = content[:yaml_end_pos + len(yaml_end_marker)].decode('utf-8')
                print("\nYAML content extracted.")

                print("Testing RecursionSafeBaseLoader:")
                try:
                    result = yaml.load(yaml_content, Loader=RecursionSafeBaseLoader)
                    print(f"SUCCESS: Loaded {len(result)} top-level keys")
                    print(f"Recursive structure: {result.get('a', {}).get('a') is result['a']}")

                    # Compare with BaseLoader behavior
                    print("\nFor comparison, BaseLoader fails:")
                    try:
                        result_base = yaml.load(yaml_content, Loader=yaml.BaseLoader)
                        print("BaseLoader unexpectedly succeeded")
                    except Exception as e:
                        print(f"BaseLoader failed as expected: {type(e).__name__}: {e}")

                except Exception as e:
                    print(f"ERROR: {type(e).__name__}: {e}")
                    import traceback
                    traceback.print_exc()

    finally:
        # Clean up
        if os.path.exists(temp_filename):
            os.unlink(temp_filename)

if __name__ == "__main__":
    test_with_real_asdf()"}

