    def match_placeholder_shown(self, el):
        """Match placeholder-shown.

        An element matches :placeholder-shown if it has a placeholder attribute
        and its placeholder is currently being shown. This happens when:
        - For input elements: the value attribute is empty
        - For textarea elements: the content is empty (or just whitespace/newlines in Firefox style)
        """

        # Check if element has placeholder attribute
        placeholder = self.get_attribute_by_name(el, 'placeholder')
        if placeholder is None or placeholder == '':
            return False

        # Get the tag name
        tag_name = self.get_tag(el).lower()

        if tag_name == 'input':
            # For input elements, check if value attribute is empty
            value = self.get_attribute_by_name(el, 'value')
            # If value is None, it means no value attribute, which is equivalent to empty
            return value is None or value == ''

        elif tag_name == 'textarea':
            # For textarea elements, check if content is empty
            # Get all text content from the element
            content = ''.join([text for text in self.get_text(el, no_iframe=True)])
            # Firefox treats a single newline as empty content
            return content == '' or content == '\n'

        else:
            # Other elements don't support placeholder-shown
            return False

