def test_transpilation_between_dialects():
    """Test transpilation of SERIAL between MySQL and other dialects."""

    # Start with MySQL SERIAL
    mysql_serial = "CREATE TABLE t (id SERIAL PRIMARY KEY)"

    print("Testing cross-dialect transpilation:")
    print(f"Original MySQL: {mysql_serial}")

    # Transpile to Postgres 
    try:
        postgres_result = sqlglot.transpile(mysql_serial, read='mysql', write='postgres')
        print(f"To Postgres: {postgres_result[0]}")
    except Exception as e:
        print(f"Postgres transpilation failed: {e}")

    # Transpile to other dialects
    for dialect in ['sqlite', 'bigquery']:
        try:
            result = sqlglot.transpile(mysql_serial, read='mysql', write=dialect)
            print(f"To {dialect}: {result[0]}")
        except Exception as e:
            print(f"{dialect} transpilation failed: {e}")

def test_expanded_form():
    """Test the expanded form that SERIAL represents."""
