def _serial_to_bigint_unsigned(expression: exp.Expression) -> exp.Expression:
    """Convert SERIAL data type to BIGINT UNSIGNED NOT NULL AUTO_INCREMENT UNIQUE in MySQL."""
    if not isinstance(expression, exp.ColumnDef):
        return expression

    kind = expression.kind
    if not kind:
        return expression

    if kind.this == exp.DataType.Type.SERIAL:
        # Replace SERIAL with BIGINT UNSIGNED
        data_type = exp.DataType(this=exp.DataType.Type.UBIGINT)
        kind.replace(data_type)

        # Add the required constraints: NOT NULL, AUTO_INCREMENT, UNIQUE
        constraints = expression.args.get("constraints", [])
