import sqlglot

def test_cross_dialect():
    """Test how MySQL SERIAL behaves when transpiled to other dialects."""

    mysql_serial = "CREATE TABLE t (id SERIAL PRIMARY KEY)"

    print("Cross-dialect transpilation test:")
    print(f"Original MySQL: {mysql_serial}")

    dialects = ['postgres', 'sqlite', 'bigquery', 'snowflake']

    for dialect in dialects:
        try:
            result = sqlglot.transpile(mysql_serial, read='mysql', write=dialect)
            print(f"To {dialect.capitalize()}: {result[0]}")
        except Exception as e:
            print(f"To {dialect.capitalize()}: ERROR - {e}")

def test_roundtrip():
