    # Parse and regenerate
    try:
        result = sqlglot.transpile(sql, read='mysql', write='mysql')
        print(f"Round-trip: {result[0]}")
    except Exception as e:
        print(f"Round-trip failed: {e}")

if __name__ == "__main__":
