def add_precursor_mz(spectrum_in: SpectrumType) -> SpectrumType:
    """Add precursor_mz to correct field and make it a float.

    For missing precursor_mz field: check if there is "pepmass" entry or other
    common precursor m/z field names instead.
    For string parsed as precursor_mz: convert to float.
    """
    if spectrum_in is None:
        return None

    spectrum = spectrum_in.clone()

    # If precursor_mz is already present as string, convert to float
    precursor_mz = spectrum.get("precursor_mz", None)
    if isinstance(precursor_mz, str):
        spectrum.set("precursor_mz", float(precursor_mz.strip()))
    # If precursor_mz is missing, check for alternative field names
    elif precursor_mz is None:
        # Check for alternative precursor m/z field names in order of preference
        precursor_mz_extracted = None

        # Check pepmass first (highest priority among alternatives)
        pepmass = spectrum.get("pepmass", None)
        if pepmass is not None:
            if isinstance(pepmass, (list, tuple)) and len(pepmass) > 0:
                if isinstance(pepmass[0], (float, int)):
                    precursor_mz_extracted = pepmass[0]
                elif isinstance(pepmass[0], str):
                    try:
                        precursor_mz_extracted = float(pepmass[0].strip())
                    except ValueError:
                        pass

        # Check other common field names if pepmass wasn't found or valid
        if precursor_mz_extracted is None:
            # List of alternative field names to check
            alternative_fields = [
                "precursorMz",  # camelCase variation
                "percursormz",  # no underscore variation
            ]

            for field_name in alternative_fields:
                value = spectrum.get(field_name, None)
                if value is not None:
                    if isinstance(value, (float, int)):
                        precursor_mz_extracted = value
                        break
                    elif isinstance(value, str):
                        try:
                            precursor_mz_extracted = float(value.strip())
                            break
                        except ValueError:
                            continue

        # Set the extracted precursor_mz if found
        if precursor_mz_extracted is not None:
            spectrum.set("precursor_mz", precursor_mz_extracted)
        else:
            print("No precursor_mz found in metadata.")

    return spectrum"}

